# Reference: ?sas2r_runtime and vignette("runtime-helpers") in the sas2r package.
# Source of truth: R/runtime-*.R in the sas2r package; regenerate with
#   Rscript tools/build-runtime-template.R

# Runtime helpers: SAS value semantics. Part of the runtime every translated
# program carries; see ?sas2r_runtime. R/runtime-*.R is the source of truth
# and inst/templates/sas2r-helpers.R is generated from it.

# SAS || concatenation with SAS missing semantics: a missing operand contributes
# nothing instead of "NA".
# NOTE: SAS || pads fixed-width operands; %+% does not. If source code relies on padded concatenation, review output widths.
`%+%` <- function(a, b) {
  paste0(ifelse(is.na(a), "", sas_display(a)), ifelse(is.na(b), "", sas_display(b)))
}

# SAS . not in (1, 2) is TRUE; NA %in% c(1, 2) is FALSE, so !(NA %in% ...) is TRUE
`%notin%` <- function(a, b) {
  if (is.character(a) || is.character(b)) {
    a <- if (is.character(a)) sub(" +$", "", a) else a
    b <- if (is.character(b)) sub(" +$", "", b) else b
    a[is.na(a)] <- ""; b[is.na(b)] <- ""
  }
  !(a %in% b)
}

chr_cmp <- function(a, b, op = NULL) {
  if (!is.null(op) && (!is.character(op) || length(op) != 1L || is.na(op) ||
      !op %in% c("==", "!=", "<", "<=", ">", ">="))) {
    stop('chr_cmp: op must be NULL or one of "==", "!=", "<", "<=", ">", ">=". Use op = "==" for equality.',
         call. = FALSE)
  }
  if (missing(op) || is.null(op)) {
    if (is.character(a) || is.character(b)) {
      strip <- function(x) sub(" +$", "", x)
      a_chr <- strip(as.character(a))
      b_chr <- strip(as.character(b))
      levels <- sort(unique(c(a_chr, b_chr)), method = "radix", na.last = NA)
      a_rank <- match(a_chr, levels); b_rank <- match(b_chr, levels)
      a_na <- is.na(a) | a_chr == ""
      b_na <- is.na(b) | b_chr == ""

      res <- integer(max(length(a), length(b)))
      both_na <- a_na & b_na
      only_a_na <- a_na & !b_na
      only_b_na <- !a_na & b_na
      neither_na <- !a_na & !b_na

      res[both_na] <- 0L
      res[only_a_na] <- -1L
      res[only_b_na] <- 1L
      if (any(neither_na)) {
        lt <- a_rank < b_rank
        gt <- a_rank > b_rank
        res[neither_na & lt] <- -1L
        res[neither_na & gt] <- 1L
        res[neither_na & !lt & !gt] <- 0L
      }
      return(res)
    } else {
      a_val <- ifelse(is.na(a), -Inf, a)
      b_val <- ifelse(is.na(b), -Inf, b)
      res <- integer(max(length(a), length(b)))
      lt <- a_val < b_val
      gt <- a_val > b_val
      res[lt] <- -1L
      res[gt] <- 1L
      res[!lt & !gt] <- 0L
      return(res)
    }
  }
  if (is.character(a) || is.character(b)) {
    strip <- function(x) sub(" +$", "", x)
    a_chr <- strip(as.character(a))
    b_chr <- strip(as.character(b))
    levels <- sort(unique(c(a_chr, b_chr)), method = "radix", na.last = NA)
    a_rank <- match(a_chr, levels); b_rank <- match(b_chr, levels)
    a_na <- is.na(a) | a_chr == ""
    b_na <- is.na(b) | b_chr == ""

    both_na <- a_na & b_na
    only_a_na <- a_na & !b_na
    only_b_na <- !a_na & b_na
    neither_na <- !a_na & !b_na

    res <- logical(max(length(a), length(b)))

    if (op %in% c("==", "<=", ">=")) res[both_na] <- TRUE
    if (op %in% c("!=", "<", ">")) res[both_na] <- FALSE

    if (op %in% c("<", "<=", "!=")) res[only_a_na] <- TRUE
    if (op %in% c("==", ">", ">=")) res[only_a_na] <- FALSE

    if (op %in% c(">", ">=", "!=")) res[only_b_na] <- TRUE
    if (op %in% c("==", "<", "<=")) res[only_b_na] <- FALSE

    if (any(neither_na)) {
      cmp <- switch(op,
        "==" = a_chr == b_chr,
        "!=" = a_chr != b_chr,
        "<"  = a_rank < b_rank,
        "<=" = a_rank <= b_rank,
        ">"  = a_rank > b_rank,
        ">=" = a_rank >= b_rank
      )
      res[neither_na] <- cmp[neither_na]
    }
    return(res)
  } else {
    a_val <- ifelse(is.na(a), -Inf, a)
    b_val <- ifelse(is.na(b), -Inf, b)
    switch(op,
      "==" = a_val == b_val,
      "!=" = a_val != b_val,
      "<"  = a_val < b_val,
      "<=" = a_val <= b_val,
      ">"  = a_val > b_val,
      ">=" = a_val >= b_val
    )
  }
}

sas_sum <- function(...) {
  args <- list(...)
  if (length(args) == 0L) return(numeric(0))
  n <- max(vapply(args, length, integer(1)))
  if (n == 0L) return(numeric(0))
  total <- rep(0, n)
  any_ok <- rep(FALSE, n)
  for (a in args) {
    if (length(a) == 0L) next
    a <- rep_len(as.numeric(a), n)
    ok <- !is.na(a)
    total[ok] <- total[ok] + a[ok]
    any_ok <- any_ok | ok
  }
  total[!any_ok] <- NA_real_
  total
}

sas_mean <- function(...) {
  args <- list(...)
  if (length(args) == 0L) return(numeric(0))
  n <- max(vapply(args, length, integer(1)))
  if (n == 0L) return(numeric(0))
  total <- rep(0, n)
  cnt <- rep(0L, n)
  for (a in args) {
    if (length(a) == 0L) next
    a <- rep_len(as.numeric(a), n)
    ok <- !is.na(a)
    total[ok] <- total[ok] + a[ok]
    cnt[ok] <- cnt[ok] + 1L
  }
  out <- rep(NA_real_, n)
  has <- cnt > 0L
  out[has] <- total[has] / cnt[has]
  out
}

sas_round <- function(x, unit = 1) {
  if (any(!is.na(unit) & (!is.finite(unit) | unit <= 0)))
    stop("sas_round: rounding units must be positive and finite; nonpositive units are unsupported", call. = FALSE)
  q <- abs(x) / unit
  q <- ifelse(is.finite(q) & q < 1e15, signif(q, 15), q)
  rounded <- ifelse(q >= 2^52, q, floor(q + 0.5))
  inverse <- 1 / unit
  decimal <- rep_len(is.finite(inverse) & abs(inverse - round(inverse)) < 1e-9, length(q))
  sign(x) * ifelse(decimal, rounded / round(inverse), rounded * unit)
}

sas_compress <- function(x, chars = " ") {
  x <- as.character(x)
  for (char in unique(strsplit(chars, "", fixed = TRUE)[[1L]])) x <- gsub(char, "", x, fixed = TRUE)
  x
}

sas_substr <- function(x, pos, len = NULL) {
  if (is.null(len)) substr(x, pos, nchar(x))
  else substr(x, pos, pmax(pos + len - 1L, pos - 1L))
}

sas_min <- function(...) {
  args <- list(...)
  if (length(args) == 0L) return(numeric(0))
  # SAS MIN(x) with one argument is x, elementwise -- never a column aggregate.
  if (length(args) == 1L) return(args[[1]])
  res <- do.call(pmin, c(args, list(na.rm = TRUE)))
  all_na <- Reduce(`&`, lapply(args, is.na))
  res[all_na] <- NA_real_
  res
}

sas_max <- function(...) {
  args <- list(...)
  if (length(args) == 0L) return(numeric(0))
  if (length(args) == 1L) return(args[[1]])
  res <- do.call(pmax, c(args, list(na.rm = TRUE)))
  all_na <- Reduce(`&`, lapply(args, is.na))
  res[all_na] <- NA_real_
  res
}

sas_length <- function(x) {
  if (is.character(x)) {
    s <- sub(" +$", "", x)
    ifelse(is.na(s) | s == "", 1L, nchar(s))
  } else {
    rep.int(12L, length(x))
  }
}

sas_if_else <- function(cond, yes, no) {
  n <- max(length(cond), length(yes), length(no))
  cond <- rep_len(cond, n)
  idx <- !is.na(cond) & cond
  if (length(no) == 1L && is.logical(no) && is.na(no)) {
    # New-variable form: the false branch is bare NA, so the yes branch is the
    # only carrier of class information.
    out <- rep_len(yes, n)
    out[!idx] <- NA
    return(out)
  }
  yes <- rep_len(yes, n)
  out <- rep_len(no, n)
  out[idx] <- yes[idx]
  out
}

sas_display <- function(x) {
  if (is.numeric(x)) {
    out <- character(length(x))
    na_idx <- is.na(x)
    out[na_idx] <- "."
    if (any(!na_idx)) {
      out[!na_idx] <- vapply(x[!na_idx], function(value) format(value, digits = 12, trim = TRUE, scientific = FALSE), "")
    }
  } else {
    out <- as.character(x)
    out[is.na(x)] <- ""
  }
  out
}

sas_missing <- function(x) is.na(x) | (is.character(x) & !is.na(x) & grepl("^ *$", x))

sas_true <- function(x) {
  if (is.character(x)) x <- suppressWarnings(as.numeric(trimws(x)))
  !is.na(x) & x != 0
}

# Runtime helpers: librefs and data access. Part of the runtime every
# translated program carries; see ?sas2r_runtime.

# The libref registry is the `.sas2r_registry` list the bundle's autoexec.R
# defines. The runtime finds it where it was loaded:
# lexically first -- the environment the runtime was sourced into, which is
# how a bundle program and a test harness both work -- then, for the package
# form of the runtime, in active local call frames. Package helpers must not
# fall back to the user's workspace: LIBNAME updates the registry in place.
# A standalone runtime explicitly sourced into a script's top-level environment
# uses that chosen environment, preserving direct Rscript execution.
sas2r_registry_env <- function() {
  env <- parent.env(environment())
  runtime_env <- env
  while (!identical(env, emptyenv())) {
    if ((!identical(env, globalenv()) || identical(env, runtime_env)) &&
        exists(".sas2r_registry", envir = env, inherits = FALSE)) return(env)
    env <- parent.env(env)
  }
  frames <- sys.frames()
  for (i in rev(seq_along(frames))) {
    if (!identical(frames[[i]], globalenv()) &&
        exists(".sas2r_registry", envir = frames[[i]], inherits = FALSE)) {
      return(frames[[i]])
    }
  }
  sas2r_libref_stop(
    "sas2r_no_registry",
    "No libref registry is loaded in a local environment: source the bundle's autoexec.R with local = runtime, chdir = TRUE, where runtime <- new.env()"
  )
}

sas2r_resolve_registry <- function(registry, root) {
  if (!is.list(registry)) {
    sas2r_libref_stop("sas2r_registry_error", "registry must be a list of libref entries")
  }
  if (!is.character(root) || length(root) != 1L || is.na(root) || !nzchar(root)) {
    sas2r_libref_stop("sas2r_registry_error", "root must be one directory path")
  }
  absolute <- function(p) grepl("^(/|[A-Za-z]:[/\\\\]|\\\\\\\\|~)", p)
  for (libref in names(registry)) {
    entry <- registry[[libref]]
    for (field in intersect(c("read_path", "write_path", "path"), names(entry))) {
      p <- entry[[field]]
      if (!is.character(p) || length(p) != 1L || is.na(p) || !nzchar(p)) next
      if (startsWith(p, "<FILL")) {
        sas2r_libref_stop(
          "sas2r_registry_fill",
          paste0("autoexec.R: libref ", libref, " still has a <FILL> placeholder for ",
                 field, "; set the path"))
      }
      entry[[field]] <- if (absolute(p)) path.expand(p) else file.path(root, p)
    }
    w <- if (!is.null(entry$write_path)) entry$write_path else entry$path
    if (is.character(w) && length(w) == 1L && !is.na(w) && nzchar(w)) {
      dir.create(w, showWarnings = FALSE, recursive = TRUE)
    }
    registry[[libref]] <- entry
  }
  registry
}

sas2r_libname_assign <- function(libref, read_path, write_path = read_path,
                                 engine = "sas7bdat", write = "rds") {
  env <- sas2r_registry_env()
  registry <- get(".sas2r_registry", envir = env, inherits = FALSE)
  key <- tolower(libref)
  read_path <- sas2r_assignment_path(read_path, env)
  bindings <- get0(".sas2r_library_bindings", envir = env, inherits = FALSE)
  if (missing(write_path) && !is.null(bindings)) {
    # A repeated LIBNAME (including an alias or a bind after CLEAR) names the
    # same physical data. Keep the generated members in that library visible.
    paths <- vapply(bindings, function(entry) {
      sas2r_assignment_path(entry$read_path, env)
    }, character(1))
    idx <- match(read_path, paths)
    if (!is.na(idx)) {
      write_path <- bindings[[idx]]$write_path
    } else {
      root <- get(".sas2r_output_root", envir = env, inherits = FALSE)
      write_path <- file.path(root, "libraries", paste0(key, "_", substr(cli::hash_sha256(read_path), 1L, 16L)))
    }
  } else {
    write_path <- sas2r_assignment_path(write_path, env)
  }
  registry[[key]] <- list(
    read_path = read_path,
    write_path = write_path,
    engine = engine,
    write = write
  )
  assign(".sas2r_registry", registry, envir = env)
  if (!is.null(bindings)) {
    existing <- which(vapply(bindings, function(entry) {
      identical(sas2r_assignment_path(entry$read_path, env), read_path)
    }, logical(1)))
    idx <- if (length(existing)) existing[1L] else length(bindings) + 1L
    bindings[[idx]] <- registry[[key]]
    assign(".sas2r_library_bindings", bindings, envir = env)
  }
  invisible(registry[[key]])
}

sas2r_assignment_path <- function(path, env) {
  root <- get0(".sas2r_execution_root", envir = env, inherits = FALSE,
               ifnotfound = getwd())
  if (!grepl("^(/|[A-Za-z]:[/\\\\]|\\\\\\\\|~)", path)) path <- file.path(root, path)
  normalizePath(path.expand(path), winslash = "/", mustWork = FALSE)
}

sas2r_tlf_relative_path <- function(path) {
  if (!is.character(path) || length(path) != 1L || is.na(path) || !nzchar(path))
    stop("Report path must be a non-empty relative path", call. = FALSE)
  path <- gsub("\\\\", "/", path)
  path <- sub("^(\\./)+", "", path)
  if (grepl("^(/|[A-Za-z]:|~)", path))
    stop("Use a relative logical report path within the output root", call. = FALSE)
  parts <- character()
  for (part in strsplit(path, "/", fixed = TRUE)[[1L]]) {
    if (part %in% c("", ".")) next
    if (part == "..") {
      if (!length(parts)) stop("Report path escapes the logical output root", call. = FALSE)
      parts <- utils::head(parts, -1L)
    } else parts <- c(parts, part)
  }
  path <- paste(parts, collapse = "/")
  if (!nzchar(path)) stop("Report path must name a file", call. = FALSE)
  path
}

sas_output_path <- function(path, env = parent.frame()) {
  # Follow the translated function's lexical scope, stopping before the
  # workspace unless the standalone helper was itself sourced there.
  while (!identical(env, emptyenv()) && !identical(env, globalenv()) &&
         !exists(".sas2r_output_root", envir = env, inherits = FALSE)) {
    env <- parent.env(env)
  }
  root <- if (!identical(env, globalenv()) || identical(environment(sas_output_path), env))
    get0(".sas2r_output_root", envir = env, inherits = FALSE)
  if (!is.character(root) || length(root) != 1L || is.na(root) || !nzchar(root))
    stop("A runtime output root is required; source autoexec.R into a local environment", call. = FALSE)
  dest <- file.path(root, "tlf", sas2r_tlf_relative_path(path))
  dir.create(dirname(dest), recursive = TRUE, showWarnings = FALSE)
  dest
}

sas2r_libname_clear <- function(libref) {
  env <- sas2r_registry_env()
  registry <- get(".sas2r_registry", envir = env, inherits = FALSE)
  if (identical(tolower(libref), "_all_")) registry <- list() else registry[[tolower(libref)]] <- NULL
  assign(".sas2r_registry", registry, envir = env)
  invisible(NULL)
}

sas2r_libref_stop <- function(cls, msg, identifiers = character()) {
  stop(structure(
    class = c(cls, "sas2r_libref_error", "error", "condition"),
    list(message = msg, call = NULL, identifiers = identifiers)
  ))
}

# The library a libref names is chosen from SAS source or from configuration
# and is deliberately *not* held inside the project -- a study library lives
# where the study keeps it. The confinement that does apply is this one: a
# member is a SAS dataset name, never a path, so the file it resolves to has to
# sit in the library directory itself and cannot walk out of it.
sas2r_lib_entry <- function(libref) {
  registry <- get(".sas2r_registry", envir = sas2r_registry_env(), inherits = FALSE)
  reg <- registry[[tolower(libref)]]
  if (is.null(reg)) {
    sas2r_libref_stop("sas2r_unknown_libref",
                      paste0("Unknown libref: ", libref), identifiers = libref)
  }
  reg
}

sas2r_lib_member_path <- function(dir, member, ext) {
  if (!is.character(member) || length(member) != 1L || is.na(member) ||
      !nzchar(member) || grepl("[/\\\\]", member) ||
      member %in% c(".", "..")) {
    sas2r_libref_stop("sas2r_libref_member_error",
                      paste0("Unsafe dataset member name: ", member))
  }
  file.path(dir, paste0(member, ext))
}

sas2r_lib_member_file <- function(reg, member) {
  sas2r_lib_member_path("", member, "")
  write_dir <- if (!is.null(reg$write_path)) reg$write_path else reg$path
  read_dir <- if (!is.null(reg$read_path)) reg$read_path else reg$path
  locations <- list(list(path = write_dir, types = unique(c(reg$write, "rds", "sas7bdat", "xpt"))),
                    list(path = read_dir, types = unique(c(reg$engine, "rds", "sas7bdat", "xpt"))))
  for (location in locations) {
    if (is.null(location$path) || is.na(location$path) || !nzchar(location$path)) next
    files <- list.files(location$path, full.names = TRUE)
    files <- files[!dir.exists(files)]
    for (type in location$types) {
      hits <- files[tolower(basename(files)) == paste0(tolower(member), ".", type)]
      if (length(hits) > 1L) stop("Ambiguous dataset member: ", member, call. = FALSE)
      if (length(hits)) return(list(type = type, path = hits[[1L]]))
    }
  }
  NULL
}

lib_exists <- function(libref, member) {
  if (missing(libref) || !is.character(libref) || length(libref) != 1L ||
      is.na(libref) || !nzchar(libref) || grepl(".", libref, fixed = TRUE) ||
      missing(member) || !is.character(member) || length(member) != 1L ||
      is.na(member) || !nzchar(member)) {
    stop('Use lib_exists("lib", "member") with two separate strings.', call. = FALSE)
  }
  !is.null(sas2r_lib_member_file(sas2r_lib_entry(libref), member))
}

lib_members <- function(libref) {
  if (missing(libref) || !is.character(libref) || length(libref) != 1L ||
      is.na(libref) || !grepl("^[A-Za-z_][A-Za-z0-9_]*$", libref)) {
    stop('Use lib_members("lib") with one registered library name.', call. = FALSE)
  }
  reg <- sas2r_lib_entry(libref)
  write_dir <- if (!is.null(reg$write_path)) reg$write_path else reg$path
  read_dir <- if (!is.null(reg$read_path)) reg$read_path else reg$path
  dirs <- unique(c(write_dir, read_dir))
  if (!length(dirs) || anyNA(dirs) || any(!nzchar(dirs))) {
    stop("No directory configured for libref: ", libref, call. = FALSE)
  }
  names <- character()
  for (dir in dirs) {
    if (!dir.exists(dir)) {
      if (identical(dir, write_dir) && !file.exists(dir)) next
      stop("Library directory is unavailable: ", dir, call. = FALSE)
    }
    if (file.access(dir, 4L) != 0L) stop("Library directory is unreadable: ", dir, call. = FALSE)
    files <- list.files(dir, pattern = "\\.(rds|sas7bdat|xpt)$", full.names = TRUE, ignore.case = TRUE)
    names <- c(names, sub("\\.[^.]+$", "", basename(files[!dir.exists(files)])))
  }
  names <- sort(unique(names[grepl("^[A-Za-z_][A-Za-z0-9_]*$", names)]), method = "radix")
  names[vapply(names, function(member) !is.null(sas2r_lib_member_file(reg, member)), logical(1))]
}

sas2r_fold_names <- function(df) {
  names(df) <- tolower(names(df))
  df
}

# Frames read by lib_read() carry class sas2r_dataset so `df$AVAL` and
# `df[["aval"]]` resolve case-insensitively, as SAS variable names do.
`$.sas2r_dataset` <- function(x, name) {
  idx <- match(tolower(name), tolower(names(x)))
  if (!is.na(idx)) x[[idx]] else NULL
}

`[[.sas2r_dataset` <- function(x, i, exact = TRUE) {
  if (is.character(i) && length(i) == 1L) {
    idx <- match(tolower(i), tolower(names(x)))
    if (!is.na(idx)) return(x[[idx]])
  }
  NextMethod()
}

`$<-.sas2r_dataset` <- function(x, name, value) {
  idx <- match(tolower(name), tolower(names(x)))
  if (!is.na(idx)) name <- names(x)[idx]
  NextMethod()
}

`[[<-.sas2r_dataset` <- function(x, i, value) {
  if (is.character(i) && length(i) == 1L) {
    idx <- match(tolower(i), tolower(names(x)))
    if (!is.na(idx)) i <- names(x)[idx]
  }
  NextMethod()
}

lib_read <- function(libref, member, ...) {
  # Exactly one call form: lib_read("lib", "member"). The rejected forms --
  # combined "lib.member" strings, single-argument calls that used to default
  # to work, and dataset=/table= aliases -- fail here with the canonical form
  # in the message, so a wrong call in an agent translation becomes repair
  # feedback instead of being silently reinterpreted.
  canonical <- 'lib_read("lib", "member")'
  if (length(list(...)) > 0L) {
    sas2r_libref_stop("sas2r_lib_read_arguments", paste0("lib_read(): dataset=/table= aliases are not accepted; use ",
         canonical))
  }
  if (missing(libref) || !is.character(libref) || length(libref) != 1L ||
      is.na(libref) || !nzchar(libref)) {
    sas2r_libref_stop("sas2r_lib_read_arguments", paste0("lib_read() takes a libref and a member as two separate strings; use ",
         canonical))
  }
  # The combined form lives in the libref position only. The member is left
  # to sas2r_lib_member_path(), whose path-traversal refusal must keep its
  # own classed condition rather than be pre-empted here.
  if (grepl(".", libref, fixed = TRUE)) {
    sas2r_libref_stop("sas2r_lib_read_arguments", paste0('lib_read() does not accept combined "lib.member" references; use ',
         canonical))
  }
  if (missing(member)) {
    sas2r_libref_stop("sas2r_lib_read_arguments", paste0("lib_read() needs both a libref and a member; use ", canonical,
         ' -- a single-argument call no longer defaults to "work".'))
  }
  if (!is.character(member) || length(member) != 1L || is.na(member) || !nzchar(member)) {
    sas2r_libref_stop("sas2r_lib_read_arguments", paste0("lib_read() takes a libref and a member as two separate strings; use ",
         canonical))
  }
  reg <- sas2r_lib_entry(libref)
  w_dir <- if (!is.null(reg$write_path)) reg$write_path else reg$path
  r_dir <- if (!is.null(reg$read_path)) reg$read_path else reg$path
  target <- sas2r_lib_member_file(reg, member)
  if (is.null(target)) {
    dirs <- unique(c(w_dir, r_dir))
    dirs <- dirs[!is.na(dirs) & nzchar(dirs)]
    searched <- unlist(lapply(dirs, function(dir) {
      vapply(c(".rds", ".sas7bdat", ".xpt"), function(ext) {
        sas2r_lib_member_path(dir, member, ext)
      }, character(1))
    }))
    env <- sas2r_registry_env()
    root <- get0(".sas2r_execution_root", envir = env, inherits = FALSE,
                 ifnotfound = getwd())
    sas2r_libref_stop("sas2r_dataset_not_found",
      paste0("Dataset not found: ", libref, ".", member,
        "\nSearched: ", paste(searched, collapse = ", "), "\nExecution root: ", root),
      identifiers = paste(libref, member, sep = "."))
  }
  df <- if (target$type == "rds") readRDS(target$path)
  else if (target$type == "sas7bdat") haven::read_sas(target$path)
  else if (target$type == "xpt") haven::read_xpt(target$path)
  # SAS keeps a date as a number of days from 1960-01-01 and a format that says
  # to show it as a date. A column the SAS source declares that way is stored
  # as an R Date (see lib_write()) and handed back here as the SAS number, so
  # date arithmetic in a later program is the SAS arithmetic. The format
  # attribute goes with the class: R arithmetic copies attributes, and a
  # duration computed from two dates must not look like a date.
  dates <- get0(".sas2r_output_dates", envir = sas2r_registry_env(), inherits = TRUE)
  dates <- if (is.list(dates)) dates[[tolower(paste(libref, member, sep = "."))]]
  if (is.character(dates) && !is.null(names(dates))) {
    origin <- -as.numeric(as.Date("1960-01-01"))
    for (name in names(dates)) {
      at <- which(tolower(names(df)) == tolower(name))
      if (length(at) != 1L || !inherits(df[[at]], "Date")) next
      x <- unclass(df[[at]])
      storage.mode(x) <- "double"
      present <- !is.na(x)
      x[present] <- x[present] + origin
      attr(x, "format.sas") <- NULL
      df[[at]] <- x
    }
  }
  class(df) <- unique(c("sas2r_dataset", class(df)))
  df
}

lib_write <- function(df, libref, member, ...) {
  # Exactly one call form: lib_write(df, "lib", "member"), data frame first.
  # See lib_read() for why the other forms are rejected rather than absorbed.
  canonical <- 'lib_write(df, "lib", "member")'
  if (length(list(...)) > 0L) {
    sas2r_libref_stop("sas2r_lib_write_arguments", paste0("lib_write(): dataset=/table= aliases are not accepted; use ",
         canonical))
  }
  if (missing(df)) {
    sas2r_libref_stop("sas2r_lib_write_arguments", paste0("lib_write() takes the data frame first; use ", canonical))
  }
  if (is.character(df)) {
    sas2r_libref_stop("sas2r_lib_write_arguments", paste0("lib_write() takes the data frame first; use ", canonical,
         ' -- the first argument was the string "', df[1], '".'))
  }
  if (missing(libref) || !is.character(libref) || length(libref) != 1L ||
      is.na(libref) || !nzchar(libref)) {
    sas2r_libref_stop("sas2r_lib_write_arguments", paste0("lib_write() takes the libref and member as two separate strings after ",
         "the data frame; use ", canonical))
  }
  if (grepl(".", libref, fixed = TRUE)) {
    sas2r_libref_stop("sas2r_lib_write_arguments", paste0('lib_write() does not accept combined "lib.member" references; use ',
         canonical))
  }
  if (missing(member)) {
    sas2r_libref_stop("sas2r_lib_write_arguments", paste0("lib_write() needs both a libref and a member; use ", canonical,
         ' -- a two-argument call no longer defaults to "work".'))
  }
  if (!is.character(member) || length(member) != 1L || is.na(member) || !nzchar(member)) {
    sas2r_libref_stop("sas2r_lib_write_arguments", paste0("lib_write() takes the libref and member as two separate strings after ",
         "the data frame; use ", canonical))
  }
  reg <- sas2r_lib_entry(libref)
  w_dir <- if (!is.null(reg$write_path)) reg$write_path else reg$path
  if (is.null(w_dir) || is.na(w_dir) || !nzchar(w_dir)) {
    sas2r_libref_stop("sas2r_library_unavailable", paste0("No writable path configured for libref: ", libref), identifiers = libref)
  }
  dir.create(w_dir, showWarnings = FALSE, recursive = TRUE)
  fmt <- if (is.null(reg$write)) "rds" else reg$write
  df <- as.data.frame(df)
  if (!fmt %in% c("rds", "xpt")) sas2r_libref_stop("sas2r_write_format", paste0("Unsupported write format: ", fmt))
  # A column the SAS source declares with a date format (`.sas2r_output_dates`
  # in `_sas2r_formats.R`, one entry per output dataset) is stored as an R
  # Date. Only what is stored changes: the program keeps, and is returned, its
  # own data, and lib_read() gives a later program the SAS day number again.
  # A column is converted only when it is a plain number and every value comes
  # back exactly, so reading returns the numbers written; one value that would
  # not, such as some fractional day counts, leaves the whole column as it is.
  # A missing value is never computed on, which keeps a special missing
  # value's tag. A column that is already a Date is left.
  stored <- df
  dates <- get0(".sas2r_output_dates", envir = sas2r_registry_env(), inherits = TRUE)
  dates <- if (is.list(dates)) dates[[tolower(paste(libref, member, sep = "."))]]
  if (is.character(dates) && !is.null(names(dates))) {
    origin <- -as.numeric(as.Date("1960-01-01"))
    for (name in names(dates)) {
      at <- which(tolower(names(stored)) == tolower(name))
      if (length(at) != 1L) next
      x <- stored[[at]]
      if (!is.numeric(x) || !is.null(oldClass(x))) next
      present <- !is.na(x)
      shifted <- as.double(x[present]) - origin
      if (!identical(shifted + origin, as.double(x[present]))) next
      storage.mode(x) <- "double"
      x[present] <- shifted
      if (is.null(attr(x, "format.sas", exact = TRUE))) attr(x, "format.sas") <- dates[[name]]
      class(x) <- "Date"
      stored[[at]] <- x
    }
  }
  target <- sas2r_lib_member_path(w_dir, member, paste0(".", fmt))
  pending <- tempfile(".sas2r-write-", tmpdir = w_dir, fileext = paste0(".", fmt))
  on.exit(unlink(pending), add = TRUE)
  # haven names an XPT member after its file, and the temporary file's name is
  # not a SAS name: name the member after the file it becomes.
  if (fmt == "rds") saveRDS(stored, pending) else
    haven::write_xpt(stored, pending, name = sub("[.]xpt$", "", basename(target), ignore.case = TRUE))
  if (!file.rename(pending, target)) sas2r_libref_stop("sas2r_library_unavailable", paste0("Could not replace dataset member: ", target))
  invisible(df)
}

lib_delete <- function(libref, members) {
  if (!is.character(members) || anyNA(members) ||
      any(!grepl("^[A-Za-z_][A-Za-z0-9_]*$", members)) ||
      any(toupper(members) == "_ALL_")) {
    sas2r_libref_stop("sas2r_unsupported_dataset_delete",
      "lib_delete() supports explicit member names only; expand dataset lists before calling")
  }
  reg <- sas2r_lib_entry(libref)
  write_dir <- if (!is.null(reg$write_path)) reg$write_path else reg$path
  read_dir <- if (!is.null(reg$read_path)) reg$read_path else reg$path
  if (is.null(write_dir) || !nzchar(write_dir)) {
    sas2r_libref_stop("sas2r_unsupported_dataset_delete",
      paste0("No writable path configured for libref: ", libref))
  }
  files_in <- function(dir) {
    if (is.null(dir) || !dir.exists(dir)) return(character())
    files <- list.files(dir, pattern = "\\.(rds|xpt|sas7bdat)$", full.names = TRUE,
                        ignore.case = TRUE)
    files[!dir.exists(files)]
  }
  stem <- function(files) tolower(sub("\\.[^.]+$", "", basename(files)))
  members <- unique(tolower(members))
  separate_input <- !is.null(read_dir) &&
    !identical(normalizePath(read_dir, winslash = "/", mustWork = FALSE),
               normalizePath(write_dir, winslash = "/", mustWork = FALSE))
  if (separate_input && any(members %in% stem(files_in(read_dir)))) {
    sas2r_libref_stop("sas2r_unsupported_dataset_delete",
      paste0("Cannot delete ", libref,
        " members backed by a separate input directory; input files were preserved"))
  }
  files <- files_in(write_dir)
  targets <- files[stem(files) %in% members]
  absent <- setdiff(members, stem(targets))
  for (member in absent) message("Dataset not found: ", libref, ".", member)
  if (length(targets) && !all(file.remove(targets))) {
    sas2r_libref_stop("sas2r_dataset_delete_failed",
      paste0("Could not delete all requested datasets in ", write_dir))
  }
  invisible(unique(stem(targets)))
}

# Runtime helpers: PROC SORT and MERGE. Part of the runtime every translated
# program carries; see ?sas2r_runtime.

# NOTE: NODUPKEY dedups adjacent sorted keys; distinct() semantics match only after sorting -- which this pipeline guarantees.
sas_sort <- function(df, by, descending = character(), ...) {
  # Rank of each SAS missing value, used to order BY values: NA where x is not
  # missing, 0 for ._, 1 for . (an untagged NA or NaN), 2-27 for .A-.Z. Special
  # missing values are haven tagged NAs; haven reads them with lower-case tags
  # while R code may write upper-case ones, so tags compare case-insensitively.
  # A tag outside ._ and .A-.Z ranks as an ordinary missing value.
  sas2r_missing_rank <- function(x) {
    out <- rep(NA_integer_, length(x))
    miss <- is.na(x)
    out[miss] <- 1L
    if (is.double(x) && any(miss)) {
      tag <- tolower(haven::na_tag(x[miss]))
      tag[is.na(tag)] <- "."
      rank <- match(tag, c("_", ".", letters)) - 1L
      rank[is.na(rank)] <- 1L
      out[miss] <- rank
    }
    out
  }
  # Every BY variable is resolved before the empty-data return: PROC SORT
  # refuses a missing BY variable whether or not there are rows to sort.
  idx <- vapply(by, function(v) {
    hit <- which(tolower(names(df)) == tolower(v))
    if (!length(hit)) {
      stop("sas_sort: by variable not found in dataset: ", v, call. = FALSE)
    }
    # SAS names are case-insensitive, so two columns that differ only by case
    # leave the BY variable undefined: refuse, as sas_merge() does.
    if (length(hit) > 1L) {
      stop("sas_sort: by variable ", v, " matches more than one column in the dataset: ",
           paste(names(df)[hit], collapse = ", "), call. = FALSE)
    }
    hit
  }, integer(1))
  if (nrow(df) == 0L) return(df)
  cols <- lapply(seq_along(by), function(i) {
    v <- by[[i]]
    x <- df[[idx[[i]]]]
    # SAS has no factors: order a factor by its values, not its level codes,
    # so the order agrees with how sas_merge() matches the same key.
    if (is.factor(x)) x <- as.character(x)
    desc <- tolower(v) %in% tolower(descending)
    if (is.double(x)) {
      # SAS orders ._ < . < .A < ... < .Z < every number: missing values take
      # their rank 0-27 and numbers rank above them.
      key <- as.double(sas2r_missing_rank(x))
      present <- is.na(key)
      key[present] <- 28 + rank(xtfrm(x[present]), ties.method = "min")
      return(if (desc) -key else key)
    }
    if (is.character(x)) {
      x <- sub(" +$", "", x)
      x[x == "" & !is.na(x)] <- NA_character_
      x <- match(x, sort(unique(x), method = "radix", na.last = NA))
    }
    if (desc) {
      rank(-xtfrm(x), na.last = TRUE, ties.method = "min")
    } else {
      rank(xtfrm(x), na.last = FALSE, ties.method = "min")
    }
  })
  ord <- do.call(order, c(cols, list(method = "radix")))
  df[ord, , drop = FALSE]
}

sas_merge <- function(a, b, by,
                      keep = c("full", "both", "left", "right", "left_only",
                               "right_only"), ...) {
  # The BY columns of df rewritten for matching only, the way SAS compares BY
  # values. Character (and factor) values: trailing blanks never distinguish
  # values, and a blank value is the missing one, so trailing spaces are dropped
  # and NA becomes "". Leading blanks still count. Double values: every missing
  # value becomes one NA and a companion column carries its lower-case special
  # missing tag, because .A and . are distinct BY values that vctrs would
  # otherwise treat as equal. Other columns are unchanged.
  sas2r_by_key <- function(df, cols) {
    key <- as.data.frame(df[cols])
    for (i in seq_along(cols)) {
      x <- key[[i]]
      if (is.character(x) || is.factor(x)) {
        x <- sub(" +$", "", as.character(x))
        x[is.na(x)] <- ""
        key[[i]] <- x
      } else if (is.double(x)) {
        key[[paste0(".sas2r_tag_", i)]] <- tolower(haven::na_tag(x))
        x[is.na(x)] <- NA_real_
        key[[i]] <- x
      }
    }
    key
  }
  keep <- match.arg(keep)
  # SAS variable names are case-insensitive: find each BY variable in both
  # inputs, then spell every column of b the way a spells it.
  idx_a <- match(tolower(by), tolower(names(a)))
  idx_b <- match(tolower(by), tolower(names(b)))
  absent <- by[is.na(idx_a) | is.na(idx_b)]
  if (length(absent)) {
    stop("sas_merge: by variable not found in dataset: ", absent[1], call. = FALSE)
  }
  # Refuse what case-insensitive matching cannot decide: a BY variable that
  # matches two columns of one input, or two columns of b that a's spelling
  # would merge into one. Case-only pairs nothing renames are left alone.
  for (v in by) for (nm in list(names(a), names(b))) {
    hits <- nm[tolower(nm) == tolower(v)]
    if (length(hits) > 1L) {
      stop("sas_merge: by variable ", v, " matches more than one column in a dataset: ",
           paste(hits, collapse = ", "), call. = FALSE)
    }
  }
  a_pos <- match(tolower(names(b)), tolower(names(a)))
  renamed <- names(b)
  renamed[!is.na(a_pos)] <- names(a)[a_pos[!is.na(a_pos)]]
  for (v in unique(renamed[duplicated(renamed)])) {
    from <- unique(names(b)[renamed == v])
    if (length(from) > 1L) {
      stop("sas_merge: columns ", paste(from, collapse = ", "),
           " of the second dataset both match column ", v, " of the first",
           call. = FALSE)
    }
  }
  names(b) <- renamed
  # SAS refuses a BY variable that is character in one input and numeric in
  # the other. Dates count as numeric; factors count as character.
  is_chr <- function(x) is.character(x) || is.factor(x)
  is_num <- function(x) is.numeric(x) || is.double(x)
  for (i in seq_along(by)) {
    xa <- a[[idx_a[i]]]; xb <- b[[idx_b[i]]]
    if ((is_chr(xa) && is_num(xb)) || (is_num(xa) && is_chr(xb))) {
      stop("sas_merge: by variable ", by[i],
           " is numeric in one dataset and character in the other", call. = FALSE)
    }
  }
  by <- names(a)[idx_a]
  # SAS has no factors. Where both inputs supply a column, a factor on either
  # side is combined as character: assigning between a factor and a character
  # vector, or between factors with different levels, writes level codes or NA.
  # Factors that share their levels combine correctly and are left alone.
  for (v in intersect(names(a), names(b))) {
    fa <- is.factor(a[[v]]); fb <- is.factor(b[[v]])
    if ((fa || fb) && !(fa && fb && setequal(levels(a[[v]]), levels(b[[v]])))) {
      if (fa) a[[v]] <- as.character(a[[v]])
      if (fb) b[[v]] <- as.character(b[[v]])
    }
  }
  # Keys are compared through sas2r_by_key(); the returned values stay as given.
  # One group id per row serves both the duplicate checks and the join.
  ids <- vctrs::vec_group_id(sas2r_by_key(rbind(a[by], b[by]), by))
  ids_a <- ids[seq_len(nrow(a))]
  ids_b <- ids[nrow(a) + seq_len(nrow(b))]
  dup_a <- anyDuplicated(ids_a) > 0L
  dup_b <- anyDuplicated(ids_b) > 0L
  if (dup_a && dup_b)
    stop("sas_merge: many-to-many merge on keys (", paste(by, collapse = ", "),
         ") -- SAS row-walking semantics cannot be reproduced by a join. ",
         "This unit requires the PDV-faithful path.", call. = FALSE)
  overlap <- setdiff(intersect(names(a), names(b)), by)
  if ((dup_a || dup_b) && length(overlap)) {
    stop("sas_merge: duplicate keys with shared non-key columns (",
         paste(overlap, collapse = ", "),
         ") require SAS observation-by-observation MERGE semantics; defer this unit",
         call. = FALSE)
  }
  a_cols <- names(a); b_cols <- names(b)
  a$.in_a <- rep(TRUE, nrow(a)); b$.in_b <- rep(TRUE, nrow(b))
  key_id <- ".sas2r_merge_key"
  while (key_id %in% c(names(a), names(b))) key_id <- paste0(key_id, "_")
  a[[key_id]] <- ids_a
  b[[key_id]] <- ids_b
  m <- merge(a, b, by = key_id, all = TRUE, suffixes = c(".sas2r_a", ""))
  for (v in by) {
    missing_right <- is.na(m$.in_b)
    m[[v]][missing_right] <- m[[paste0(v, ".sas2r_a")]][missing_right]
    m[[paste0(v, ".sas2r_a")]] <- NULL
  }
  m[[key_id]] <- NULL
  a[[key_id]] <- NULL; b[[key_id]] <- NULL
  # SAS overlap rule: the later dataset's value wins where both contribute
  for (v in setdiff(intersect(names(a), names(b)), c(by, ".in_a", ".in_b"))) {
    left <- m[[paste0(v, ".sas2r_a")]]
    miss <- is.na(m$.in_b)
    if (any(miss)) m[[v]][miss] <- left[miss]
    m[[paste0(v, ".sas2r_a")]] <- NULL
  }
  ina <- !is.na(m$.in_a); inb <- !is.na(m$.in_b)
  rows <- switch(keep, both = ina & inb, left = ina, right = inb,
                 left_only = ina & !inb, right_only = inb & !ina, full = ina | inb)
  m <- m[rows, , drop = FALSE]
  m$.in_a <- NULL; m$.in_b <- NULL
  # SAS output shape, not base::merge's: columns follow the contributing
  # datasets in statement order, and rows follow the BY ordering under SAS
  # collation (missing lowest, stable), which sas_sort already implements.
  m <- m[, c(a_cols, setdiff(b_cols, a_cols)), drop = FALSE]
  sas_sort(m, by = by)
}

# Runtime helpers: formats. Part of the runtime every translated program
# carries; see ?sas2r_runtime.

apply_format <- function(x, fmt,
                         catalog = get0(".sas2r_formats", envir = parent.frame(), inherits = TRUE)) {
  if (is.null(fmt)) return(as.character(x))
  if (is.character(fmt)) {
    if (length(fmt) != 1L || is.na(fmt) || !nzchar(fmt))
      stop("Format name must be one non-empty string", call. = FALSE)
    name <- tolower(sub("\\.$", "", fmt))
    if (grepl("[0-9](\\.[0-9]+)?$", name))
      stop("SAS format widths and decimal specifications are not supported: ", fmt,
        "; preserve the source formatting explicitly; do not drop the width.", call. = FALSE)
    entry <- catalog[[name]]
    if (is.null(entry)) stop("SAS format not found in catalog: ", fmt, call. = FALSE)
    fmt <- entry
  }
  fmt_key <- function(v) {
    if (is.na(v)) NA_character_
    else if (is.numeric(v)) format(v, scientific = FALSE, trim = TRUE)
    else as.character(v)
  }
  key <- if (is.numeric(x)) vapply(x, fmt_key, character(1)) else as.character(x)
  out <- if (!is.null(fmt$other)) rep(fmt$other, length(x)) else key
  names_key <- names(fmt$values)
  if (is.numeric(x)) {
    numeric_keys <- suppressWarnings(as.numeric(names_key))
    matched <- match(x, numeric_keys)
    # Only the ordinary SAS missing key represents an NA numeric input.
    matched[is.na(x)] <- match(".", names_key)
  } else {
    key <- sub(" +$", "", key)
    key[is.na(key)] <- ""
    matched <- match(key, sub(" +$", "", names_key))
  }
  hit <- !is.na(matched)
  out[hit] <- unname(fmt$values[matched[hit]])
  if (!is.null(fmt$ranges)) {
    for (r in fmt$ranges) {
      lower <- if (isTRUE(r$lo_excl)) x > r$lo else x >= r$lo
      upper <- if (isTRUE(r$hi_excl)) x < r$hi else x <= r$hi
      inr <- !is.na(x) & lower & upper & !hit
      out[inr] <- r$label
      hit <- hit | inr
    }
  }
  out[is.na(x) & !hit & is.null(fmt$other)] <- NA_character_
  out
}

sas_put <- function(x, fmt,
                    catalog = get0(".sas2r_formats", envir = parent.frame(), inherits = TRUE)) {
  apply_format(x, fmt, catalog = catalog)
}

# Runtime helpers: %INCLUDE. Part of the runtime every translated program
# carries; see ?sas2r_runtime.

sas2r_source_include <- function(relative_path, envir = parent.frame()) {
  fail <- function(cls, msg) {
    stop(structure(
      class = c(cls, "sas2r_include_error", "error", "condition"),
      list(message = paste0("sas2r_source_include: ", msg), call = NULL)
    ))
  }
  if (!is.character(relative_path) || length(relative_path) != 1L ||
      is.na(relative_path) || !nzchar(relative_path)) {
    fail("sas2r_include_path_error",
         "relative_path must be one non-empty string")
  }
  if (!is.environment(envir)) {
    fail("sas2r_include_envir_error", "envir must be an environment")
  }
  path <- gsub("\\\\", "/", relative_path)
  parts <- strsplit(path, "/", fixed = TRUE)[[1]]
  if (grepl("^(/|[A-Za-z]:/|//)", path) || !length(parts) ||
      any(!nzchar(parts)) || any(parts %in% c(".", ".."))) {
    fail("sas2r_include_path_error",
         paste0("unsafe staged include path: ", relative_path))
  }

  # Where the file now being sourced lives. source() and sys.source() each keep
  # the path in a frame variable, so the innermost of those frames names the
  # staged file that reached this call -- including a module that was itself
  # reached through an include. A driver started some other way (Rscript, say)
  # has no such frame, and the working directory is the documented fallback.
  start <- NULL
  frames <- sys.frames()
  for (i in rev(seq_along(frames))) {
    fn <- tryCatch(sys.function(i), error = function(e) NULL)
    slot <- if (identical(fn, base::sys.source)) "file" else
            if (identical(fn, base::source)) "ofile" else NULL
    if (is.null(slot)) next
    found <- tryCatch(get(slot, envir = frames[[i]], inherits = FALSE),
                      error = function(e) NULL)
    if (is.character(found) && length(found) == 1L && !is.na(found) &&
        nzchar(found)) {
      start <- dirname(found)
      break
    }
  }
  if (is.null(start)) start <- getwd()

  # Bounded walk upward: it stops at the filesystem root (where dirname() is a
  # fixed point) and after a fixed number of levels, so a bundle with no
  # registry fails with this error instead of looping.
  dir <- normalizePath(start, winslash = "/", mustWork = FALSE)
  root <- NULL
  for (level in seq_len(64L)) {
    if (file.exists(file.path(dir, "autoexec.R"))) {
      root <- dir
      break
    }
    parent <- dirname(dir)
    if (identical(parent, dir)) break
    dir <- parent
  }
  if (is.null(root)) {
    fail("sas2r_include_root_error",
         paste0("no staged bundle root (autoexec.R) at or above ", start))
  }

  program_root <- get0(".sas2r_program_root", envir = envir, inherits = TRUE)
  if (is.null(program_root)) program_root <- root
  target <- file.path(program_root, path)
  if (!file.exists(target) || dir.exists(target)) {
    fail("sas2r_include_missing_error",
         paste0("staged include module not found: ", path))
  }
  # Re-confine after resolution: every component was ..-free, but a symlinked
  # directory inside the bundle resolves outside it all the same.
  real <- normalizePath(target, winslash = "/", mustWork = FALSE)
  real_root <- normalizePath(root, winslash = "/", mustWork = FALSE)
  if (!startsWith(real, paste0(real_root, "/"))) {
    fail("sas2r_include_path_error",
         paste0("staged include module resolves outside the bundle: ", path))
  }
  sys.source(real, envir = envir)
  invisible(real)
}

# Runtime helpers: generated-code plumbing. Part of the runtime every
# translated program carries; see ?sas2r_runtime.

split_ds <- function(ds, macro_vars = character()) {
  if (length(macro_vars) > 0L && is.character(ds) && length(ds) == 1L) {
    for (nm in names(macro_vars)) {
      if (nzchar(nm)) {
        ds <- gsub(paste0("&", nm, "\\b"), macro_vars[[nm]], ds)
      }
    }
  }
  p <- strsplit(ds, ".", fixed = TRUE)[[1]]
  if (length(p) == 1L) c(lib = "work", member = p[1])
  else c(lib = p[1], member = p[2])
}

sas_print_table <- function(data, file, labels = names(data), obs = TRUE,
                            pointsize = 10, rows_per_page = 40L) {
  if (!is.data.frame(data) || !ncol(data)) {
    stop("sas_print_table: data must be a data frame with at least one column.", call. = FALSE)
  }
  if (!is.character(file) || length(file) != 1L || is.na(file) || !nzchar(file)) {
    stop("sas_print_table: file must be an explicit PDF destination.", call. = FALSE)
  }
  if (!endsWith(tolower(file), ".pdf")) {
    stop(paste0("sas_print_table: file must end in .pdf (case-insensitive); ",
                "this helper writes PDF only. Use a format-appropriate writer for non-PDF output."),
         call. = FALSE)
  }
  if (!is.character(labels) || length(labels) != ncol(data) || anyNA(labels)) {
    stop("sas_print_table: labels must contain one heading per column.", call. = FALSE)
  }
  if (!is.logical(obs) || length(obs) != 1L || is.na(obs)) {
    stop("sas_print_table: obs must be TRUE or FALSE.", call. = FALSE)
  }
  if (!is.numeric(pointsize) || length(pointsize) != 1L ||
      !is.finite(pointsize) || pointsize <= 0) {
    stop("sas_print_table: pointsize must be positive and finite.", call. = FALSE)
  }
  if (!is.numeric(rows_per_page) || length(rows_per_page) != 1L ||
      !is.finite(rows_per_page) || rows_per_page < 1 || rows_per_page != floor(rows_per_page)) {
    stop("sas_print_table: rows_per_page must be a positive integer.", call. = FALSE)
  }
  columns <- lapply(data, sas_display)
  if (isTRUE(obs)) {
    columns <- c(list(as.character(seq_len(nrow(data)))), columns)
    labels <- c("Obs", labels)
  }
  # Split every cell before measuring so a multiline cell cannot overlap the
  # following record. Empty cells still occupy one line.
  split_cell <- function(x) {
    x <- gsub("\r\n?", "\n", x)
    x <- gsub("\t", " ", x, fixed = TRUE)
    lines <- strsplit(paste0(x, "\n"), "\n", fixed = TRUE)[[1L]]
    if (length(lines)) lines else ""
  }
  cells <- lapply(seq_along(columns), function(j) {
    lapply(c(labels[[j]], columns[[j]]), split_cell)
  })
  heights <- vapply(seq_len(nrow(data) + 1L), function(i) {
    max(vapply(cells, function(col) length(col[[i]]), integer(1)))
  }, integer(1))
  lines <- do.call(cbind, lapply(cells, function(col) {
    unlist(lapply(seq_along(col), function(i) {
      c(col[[i]], rep("", heights[[i]] - length(col[[i]])))
    }), use.names = FALSE)
  }))
  # Some iconv implementations transliterate even with sub = NA. Check the
  # round trip before opening the destination so substitutions cannot pass.
  text <- unique(enc2utf8(as.character(lines)))
  if (any(grepl("[[:cntrl:]]", text))) {
    stop("sas_print_table: unsupported control character in a heading or cell.", call. = FALSE)
  }
  encoded <- iconv(text, from = "UTF-8", to = "CP1252", sub = NA)
  decoded <- iconv(encoded, from = "CP1252", to = "UTF-8", sub = NA)
  if (anyNA(decoded) || any(decoded != text) || any(grepl("\u00ad", text, fixed = TRUE))) {
    stop("sas_print_table: text is outside the printable Windows-1252 PDF encoding. Use a renderer and font that support the required characters.", call. = FALSE)
  }
  header <- lines[seq_len(heights[[1L]]), , drop = FALSE]
  body <- lines[-seq_len(heights[[1L]]), , drop = FALSE]

  # Measure on a null PDF device with the same font as the destination. Never
  # implicitly open Rplots.pdf or alter the caller's graphics parameters.
  grDevices::pdf(NULL, pointsize = pointsize, family = "mono", encoding = "WinAnsi.enc")
  device <- grDevices::dev.cur()
  on.exit(if (device %in% grDevices::dev.list()) grDevices::dev.off(device), add = TRUE)
  widths <- apply(lines, 2L, function(x) max(graphics::strwidth(x, units = "inches")))
  gap <- graphics::strwidth("  ", units = "inches")
  grDevices::dev.off(device)
  margin <- 0.5
  line_height <- pointsize * 1.4 / 72
  width <- max(7, 2 * margin + sum(widths) + gap * (ncol(lines) - 1L))
  height <- max(3, 2 * margin + (nrow(header) + rows_per_page) * line_height)
  x <- margin + c(0, utils::head(cumsum(widths + gap), -1L))
  grDevices::pdf(file, width = width, height = height, pointsize = pointsize,
                 family = "mono", encoding = "WinAnsi.enc")
  device <- grDevices::dev.cur()
  graphics::par(mar = c(0, 0, 0, 0), xaxs = "i", yaxs = "i")
  pages <- max(1L, ceiling(nrow(body) / rows_per_page))
  for (page in seq_len(pages)) {
    first <- (page - 1L) * rows_per_page + 1L
    last <- min(page * rows_per_page, nrow(body))
    content <- if (first <= last) rbind(header, body[first:last, , drop = FALSE]) else header
    graphics::plot.new()
    graphics::plot.window(c(0, width), c(0, height))
    y <- height - margin - (seq_len(nrow(content)) - 0.5) * line_height
    for (j in seq_len(ncol(content))) {
      graphics::text(x[[j]], y, labels = content[, j], adj = c(0, 0.5))
    }
  }
  invisible(file)
}

